import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int aa = scanner.nextInt();
        int k, l, ttl = 0;

        for (int i = 2; i < aa; i++) {
            k = aa;
            while (k > 0) {
                ttl += (k % i);
                k /= i;
                if (k < i) {
                    ttl += k;
                    break;
                }
            }
        }

        l = aa - 2;
        for (int i = l; i > 1; i--) {
            if (ttl % i == 0 && l % i == 0) {
                ttl /= i;
                l /= i;
                break;
            }
        }

        System.out.print(ttl + "/" + l);
        System.out.println();
    }
}

